'use server'

import { revalidatePath } from 'next/cache'

// In-memory store — persists for the lifetime of the server process.
// Replace with a real database call in production.
let notificationsEnabled = false

export function getNotificationPreference(): boolean {
  return notificationsEnabled
}

export async function toggleNotification(): Promise<void> {
  notificationsEnabled = !notificationsEnabled
  // Revalidate the current page's cache so the Server Component re-renders
  // with fresh data on the next request — no redirect needed.
  revalidatePath('/')
}

